"""Recalculate diagnostics power screens from exact fitted parts and primary curves."""
from pathlib import Path
import json,hashlib,math,shutil
r=Path(__file__).resolve().parents[1];a=r/'artifacts';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();j=json.loads((a/'board.circuit.json').read_text());parts={e['name']:e for e in j if e['type']=='source_component'}
for ref,mpn in {'U_BUCK':'AP63203WU-7','L_BUCK':'SRN4018-4R7M','C_BUCK_IN':'CL32B106KBJNNNE','C_BUCK_OUT1':'CL21A226MAQNNNE','C_BUCK_OUT2':'CL21A226MAQNNNE','C_BUCK_OUT3':'CL21A226MAQNNNE','C_BUZZER':'CL21A226MAQNNNE','D_PD':'1N5819WS','D_DATA':'1N5819WS','D_BUZZER':'1N5819WS','U_TEMP':'TMP102AIDRLR','BZ_ALARM':'MLT-5020','Q_BUZZER':'AO3400A'}.items():assert parts[ref]['manufacturer_part_number']==mpn,(ref,parts[ref])
assert 'U_LDO' not in parts
historical=a/'diagnostics/historical-power';historical.mkdir(exist_ok=True)
old=a/'engineering/service-power-review.json'
if old.exists() and not(historical/old.name).exists():shutil.copyfile(old,historical/old.name)
def interpolate(file,voltage):
 d=json.loads((r/'references'/file).read_text());curve=next(c for c in d['selectPartsList'][0]['chartList']if c['asixYOption']=='Capacitance');points=sorted((float(e['x']),float(e['y']))for e in curve['data'])
 for (x,y),(xx,yy)in zip(points,points[1:]):
  if x<=voltage<=xx:return y+(yy-y)*(voltage-x)/(xx-x)
 raise ValueError(voltage)
ci=interpolate('Samsung-CL32B106KBJNNN-DCBias-25C.json',18);co=3*interpolate('Samsung-CL21A226MAQNNN-DCBias-25C.json',3.33)
assert abs(ci-6.200721882673943)<1e-8 and abs(co-40.81876956977581)<1e-8
f=1.1e6*.94;l=4.7e-6*.8;delta=3.6*(1-3.6/18)/(l*f);peak=.55+delta/2;rms=math.sqrt(.55*.31+delta**2/12);loss=.31*3.6*(1/.7-1)
evidence={p.name:sha(p) for p in(r/'references').iterdir()if p.is_file()and(p.suffix=='.pdf'or p.name.startswith('Samsung-')and p.suffix=='.json')}
report={'schema':'diagnostics-primary-power-review-v1','source_sha256':sha(a/'board.circuit.json'),'hardwareMeasurementsPerformed':False,'manufacturingRelease':False,'fittedRegulator':'AP63203WU-7','operatingInputV':[3.8,32],'absoluteInputMaximumV':35,'junctionDesignTargetC':125,'thetaJaReferenceCPerW':89,'thetaJaReferenceCondition':'Diodes Rev3-2 Note6: FR4 single layer 2oz with recommended pads; not actual-board thermal resistance','efficiencyAssumption':.70,'averageConverterLossScreenW':loss,'junctionAt45CAmbientReferenceScreenC':45+89*loss,'thermalMeasured':False,'buzzer':{'manufacturer':'Huaneng MLT-5020','ratedDriveVo_p':3.0,'operatingDriveVo_p':[2,4],'ratedFrequencyHz':4000,'ratedDuty':.5,'ratedConsumptionMaximumA':.100,'coilOhm':[9,15],'resistivePulseScreenA':3.6/9,'maximumBurstS':.1,'maximumBurstRateHz':1,'validPdRequired':True,'actualWaveformAndCurrentMeasured':False},'logicBudget':{'pdBaselineA':.1,'pulseCeilingA':.55,'averageCeilingA':.31,'dataOnly3V3TargetA':.075,'dataUsbCurrentAcceptanceA':.1,'dataUsbCurrentScreenA':.075*3.6/(.7*(4.75-.6)),'usbTransitionsNeedMeasurement':True,'noExternalLoads':True},'inductor':{'mpn':'SRN4018-4R7M','DcrMaxOhm':.084,'ratedIrmsA':1.9,'ratedIsat30PercentDropAt25CA':2,'minimumLScreenH':l,'frequencyScreenHz':f,'frequencyMinimumGuaranteed':False,'rippleScreenA':delta,'peakScreenA':peak,'thermalRmsBudgetScreenA':rms,'startupFaultCurrentLimitA':[2.5,3.1],'startupLimitExceedsPublishedIsat':True,'hotSaturationOrCurrentTested':False},'capacitors':{'inputMpn':'CL32B106KBJNNNE','inputTypicalAt18VuF':ci,'outputMpn':'CL21A226MAQNNNE','bankCount':3,'bankTypicalAt3p33VuF':co,'inputSeparateToleranceTemperatureEnduranceScreenuF':ci*.9*.85*.875,'bankSeparateToleranceTemperatureEnduranceScreenuF':co*.8*.85*.875,'acceptanceInputFlooruF':4,'acceptanceBankFlooruF':24,'remoteBuzzerCapCreditedToBank':False,'biasCurvesGuaranteed':False,'jointAgedEffectiveValuesGuaranteed':False},'powerDiodes':{'mpn':'1N5819WS','reverseMaximumV':40,'ratedAverageA':1,'forwardMaximumAt1AV':.6,'reverseLeakageAt40V25CA':.0005,'reverseLeakageAt40V100CA':.01,'thetaJaTypicalCPerW':80,'minimumDataOnlyArithmeticBuckInputV':4.75-.6,'pdNormalHeadroomToOperatingMaximumV':32-15.75,'bus18VHeadroomToAbsoluteMaximumV':35-18,'reverseIsolationIsGalvanic':False,'thermalLeakageDropoutMeasured':False},'primary_sources':evidence,'historicalLdoEvidence':{'fitted':False,'holtekOperatingInputMaximumV':30,'holtekAbsoluteInputMaximumV':33,'lossFor0p4ACoilPulseAt15p75VTo3p3VW':(15.75-3.3)*.4},'qualification':'Primary arithmetic only. Measure actual loads, USB budget at all transitions, dropout, loop/ripple, inductor current/startup/fault, switching ringing, hot saturation and mounted temperatures. No production readiness.'}
(a/'engineering/diagnostics-power-review.json').write_text(json.dumps(report,indent=2)+'\n')
# The old report stays available but explicitly carries a historical status.
v=json.loads(old.read_text());v['superseded']=True;v['supersededBy']='diagnostics-power-review.json';v['status']='Historical pre-diagnostics topology/load; not acceptance evidence for current board';old.write_text(json.dumps(v,indent=2)+'\n')
print('Recomputed exact fitted buck/diode/buzzer/capacitor screens',sha(a/'board.circuit.json'))
